import { ChangeDetectionStrategy, Component, OnInit, computed, signal } from '@angular/core';
import { AdminService } from '../../../services/admin.service';
import { MessagingService } from '../../../services/messaging.service';
import { CompassConfiguration, ConfigurationMapping, FilterSet, FilterSetOption } from '../../../models/compass-configuration.model';
import {
  cascadeMappingRemoval,
  filterLocationsInScope,
  isAllLocationsSentinel,
  isUniqueId,
  normalizeCountFields,
  PRIOR_AUTH_WORKFLOW_MEANING,
  Subroute,
  toRawSubroute
} from './location-config.helpers';
import { LocationPatch, MappingPatch } from './location-editor/location-editor.component';

@Component({
  selector: 'app-location-config',
  templateUrl: './location-config.component.html',
  styleUrls: ['./location-config.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LocationConfigComponent implements OnInit {
  // The "Prior Auth" workflow is stored under the GLIDIAN meaning in the backend config.
  readonly workflowOptions = [{ value: PRIOR_AUTH_WORKFLOW_MEANING, label: 'Prior Auth' }];
  readonly subrouteOptions: { value: Subroute; label: string }[] = [
    { value: 'incoming', label: 'Incoming' },
    { value: 'outgoing', label: 'Outgoing' }
  ];

  private _config = signal<CompassConfiguration | null>(null);
  private _originalConfig = signal<CompassConfiguration | null>(null);

  loading = signal(false);
  loadError = signal<string | null>(null);
  saving = signal(false);
  saveError = signal<string | null>(null);
  selectedWorkflow = signal<string>(PRIOR_AUTH_WORKFLOW_MEANING);
  selectedSubroute = signal<Subroute>('incoming');

  readonly locationsInScope = computed(() => {
    const cfg = this._config();
    if (!cfg) return [];
    const rawSubroute = toRawSubroute('prior-auth', this.selectedSubroute());
    return filterLocationsInScope(cfg, this.selectedWorkflow(), 'prior-auth', rawSubroute);
  });

  readonly inScopeCount = computed(() => this.locationsInScope().length);

  readonly lastSaved = computed(() => this._originalConfig()?.updtDtTm ?? null);

  readonly hasChanges = computed(() => {
    const a = this._config();
    const b = this._originalConfig();
    if (!a || !b) return false;
    return JSON.stringify(a) !== JSON.stringify(b);
  });

  readonly validationErrors = computed(() => {
    const errors: { locationId: string; label: string; messages: string[] }[] = [];
    const cfg = this._config();
    if (!cfg) return errors;
    const sets = this.locationsInScope();

    // Build duplicate-id counts in one pass.
    const idCounts = new Map<string, number>();
    for (const fs of sets) {
      const key = (fs.id ?? '').toLowerCase();
      idCounts.set(key, (idCounts.get(key) ?? 0) + 1);
    }

    for (const fs of sets) {
      // 'All Locations' (id 'all') is a "show everything" sentinel with intentionally
      // empty filters — exempt it so it never blocks saving the rest of the scope.
      if (isAllLocationsSentinel(fs)) continue;
      const messages: string[] = [];
      const idKey = (fs.id ?? '').toLowerCase();
      if (!fs.id || !fs.id.trim()) {
        messages.push('id is required');
      } else if ((idCounts.get(idKey) ?? 0) > 1) {
        messages.push('id must be unique within this scope');
      }
      if (!fs.label || !fs.label.trim()) messages.push('label is required');
      const opts = fs.filters?.[0]?.options ?? [];
      const hasOption = opts.some(o => (o?.item ?? '').trim().length > 0);
      if (!hasOption) messages.push('at least one filter option is required');
      if (!fs.filters?.[0]?.dataElement) messages.push('data element is required');
      // Mapping validation: a mapping row tied to this location must have both source and target filled.
      // This catches: (a) mapping exists for the first option but target is empty,
      // (b) a stray row was created with empty source while target was typed.
      const firstSource = opts[0]?.item;
      const matchingMapping = firstSource
        ? cfg.mapping?.find(mm => mm.keyRefValue === firstSource)
        : undefined;
      const hasEmptySourceRow = (cfg.mapping ?? []).some(mm =>
        !mm.keyRefValue?.trim() && !!mm.valueRefValue?.trim()
      );
      if (matchingMapping && !matchingMapping.valueRefValue?.trim()) {
        messages.push('mapping requires both location and facility');
      } else if (hasEmptySourceRow && fs === sets[0]) {
        // Surface orphan-row error once, on the first location in the scope (so it isn't repeated for every location).
        messages.push('mapping requires both location and facility');
      }
      if (messages.length) errors.push({ locationId: fs.id, label: fs.label ?? fs.id, messages });
    }
    return errors;
  });

  readonly canSave = computed(() => this.hasChanges() && this.validationErrors().length === 0);

  /** Ids of locations that currently have validation errors — used to flag rows in the list. */
  readonly errorLocationIds = computed(() => new Set(this.validationErrors().map(e => e.locationId)));

  /** Joined validation messages keyed by location id — shown as the row's warning tooltip. */
  readonly errorMessageById = computed(() => {
    const map = new Map<string, string>();
    for (const e of this.validationErrors()) map.set(e.locationId, e.messages.join(', '));
    return map;
  });

  readonly idErrorFor = computed(() => (id: string | null) => {
    if (!id) return null;
    const errs = this.validationErrors().find(e => e.locationId === id);
    if (!errs) return null;
    return errs.messages.find(m => m.startsWith('id ')) ?? null;
  });

  readonly labelErrorFor = computed(() => (id: string | null) => {
    if (!id) return null;
    const errs = this.validationErrors().find(e => e.locationId === id);
    if (!errs) return null;
    return errs.messages.find(m => m === 'label is required') ?? null;
  });

  readonly optionsErrorFor = computed(() => (id: string | null) => {
    if (!id) return null;
    const errs = this.validationErrors().find(e => e.locationId === id);
    if (!errs) return null;
    return errs.messages.find(m => m.includes('filter option') || m === 'data element is required') ?? null;
  });

  readonly mappingErrorFor = computed(() => (id: string | null) => {
    if (!id) return null;
    const errs = this.validationErrors().find(e => e.locationId === id);
    if (!errs) return null;
    return errs.messages.find(m => m.includes('mapping requires')) ?? null;
  });

  searchTerm = signal('');
  selectedLocationId = signal<string | null>(null);

  deleteModalVisible = signal(false);
  private _pendingDeleteId = signal<string | null>(null);

  readonly pendingDeleteLocation = computed(() => {
    const id = this._pendingDeleteId();
    if (!id) return null;
    return this.locationsInScope().find(fs => fs.id === id) ?? null;
  });

  readonly filteredLocations = computed(() => {
    const q = this.searchTerm().trim().toLowerCase();
    const list = this.locationsInScope();
    if (!q) return list;
    return list.filter(fs =>
      (fs.label ?? '').toLowerCase().includes(q) ||
      (fs.id ?? '').toLowerCase().includes(q)
    );
  });

  readonly selectedLocation = computed(() => {
    const id = this.selectedLocationId();
    if (!id) return null;
    return this.locationsInScope().find(fs => fs.id === id) ?? null;
  });

  readonly mappingForSelected = computed(() => {
    const loc = this.selectedLocation();
    const cfg = this._config();
    if (!loc || !cfg) return null;
    const source = loc.filters?.[0]?.options?.[0]?.item;
    if (!source) return null;
    const m = cfg.mapping?.find(x => x.keyRefValue === source);
    return m ? { source: m.keyRefValue, target: m.valueRefValue } : null;
  });

  readonly dataElementOptions = computed(() => {
    const cfg = this._config();
    if (!cfg) return ['schedulingLocation', 'orderingLocation'];
    const set = new Set<string>();
    cfg.workflows?.forEach(wf =>
      (wf.filterSets ?? []).forEach(fs =>
        (fs.filters ?? []).forEach(f => {
          if (f.dataElement) set.add(f.dataElement);
        })
      )
    );
    return Array.from(set).sort();
  });

  constructor(
    private adminService: AdminService,
    private messaging: MessagingService
  ) {}

  ngOnInit(): void {
    this.loadConfig();
  }

  loadConfig(): void {
    this.loading.set(true);
    this.loadError.set(null);
    this.adminService.getCompassConfiguration().subscribe({
      next: (cfg: any) => {
        if (!cfg) {
          this.loadError.set('Configuration response was empty.');
          this.loading.set(false);
          return;
        }
        this._originalConfig.set(structuredClone(cfg));
        this._config.set(structuredClone(cfg) as CompassConfiguration);
        this.loading.set(false);
      },
      error: (err: any) => {
        this.loadError.set(err?.message ?? 'Failed to load configuration.');
        this.loading.set(false);
      }
    });
  }

  discard(): void {
    const baseline = this._originalConfig();
    if (!baseline) return;
    this._config.set(structuredClone(baseline) as CompassConfiguration);
    this.saveError.set(null);
  }

  save(): void {
    if (!this.canSave()) return;
    const current = this._config();
    if (!current) return;
    this.saving.set(true);
    this.saveError.set(null);
    const payload = structuredClone(current) as CompassConfiguration;
    normalizeCountFields(payload);
    this.adminService.saveCompassConfiguration(payload as any).subscribe({
      next: () => {
        this._config.set(payload);
        this._originalConfig.set(structuredClone(payload) as CompassConfiguration);
        this.saving.set(false);
        this.messaging.success('Locations saved.');
      },
      error: (err: any) => {
        this.saving.set(false);
        this.saveError.set(err?.message ?? 'Save failed.');
      }
    });
  }

  onWorkflowChange(value: string): void {
    this.selectedWorkflow.set(value);
  }

  onSubrouteChange(value: Subroute): void {
    this.selectedSubroute.set(value);
    this.selectedLocationId.set(null);
    this.searchTerm.set('');
  }

  onSearchChange(value: string): void {
    this.searchTerm.set(value);
  }

  selectLocation(id: string): void {
    this.selectedLocationId.set(id);
  }

  addLocation(): void {
    const cfg = this._config();
    if (!cfg) return;
    const newId = this.generateUniqueId(cfg);
    const uiSubroute = this.selectedSubroute();
    const newLoc: FilterSet = {
      id: newId,
      label: 'New Location',
      route: 'prior-auth',
      subroute: toRawSubroute('prior-auth', uiSubroute),
      type: 'LocationOption',
      isDefault: 0,
      sortOrder: 0,
      // Incoming tab edits scheduling locations, Outgoing tab edits ordering locations (mirrors filter bar).
      filters: [{ dataElement: uiSubroute === 'incoming' ? 'schedulingLocation' : 'orderingLocation', options: [{ item: '' }] }],
      excludedFiltes: []
    };
    this._config.update(c => {
      if (!c) return c;
      const wf = c.workflows?.find(w => w.meaning === this.selectedWorkflow());
      if (!wf) return c;
      wf.filterSets = [...(wf.filterSets ?? []), newLoc];
      return { ...c };
    });
    this.selectedLocationId.set(newId);
  }

  onPatch(patch: LocationPatch): void {
    const id = this.selectedLocationId();
    if (!id) return;
    this._config.update(c => {
      if (!c) return c;
      const workflows = (c.workflows ?? []).map(wf => {
        if (wf.meaning !== this.selectedWorkflow()) return wf;
        const filterSets = (wf.filterSets ?? []).map(fs => {
          if (fs.id !== id) return fs;
          const updated: FilterSet = { ...fs };
          if ('id' in patch) updated.id = patch.id!;
          if ('label' in patch) updated.label = patch.label!;
          if ('sortOrder' in patch) updated.sortOrder = patch.sortOrder!;
          if ('isDefault' in patch) updated.isDefault = patch.isDefault!;
          if ('dataElement' in patch || 'options' in patch) {
            const firstFilter = updated.filters?.[0];
            if (firstFilter) {
              const newFilter = { ...firstFilter };
              if ('dataElement' in patch) newFilter.dataElement = patch.dataElement!;
              if ('options' in patch) {
                newFilter.options = (patch.options ?? []).map(s => ({ item: s }) as FilterSetOption);
              }
              updated.filters = [newFilter, ...updated.filters.slice(1)];
            }
          }
          return updated;
        });
        return { ...wf, filterSets };
      });
      return { ...c, workflows };
    });
    if ('id' in patch && patch.id) {
      this.selectedLocationId.set(patch.id);
    }
  }

  onMappingChange(next: MappingPatch | null): void {
    const loc = this.selectedLocation();
    if (!loc) return;
    const lookupKey = next?.previousSource
      ?? next?.source
      ?? loc.filters?.[0]?.options?.[0]?.item;

    this._config.update(c => {
      if (!c) return c;
      const mapping = Array.isArray(c.mapping) ? [...c.mapping] : [];
      const idx = lookupKey ? mapping.findIndex(m => m.keyRefValue === lookupKey) : -1;

      if (next === null) {
        if (idx >= 0) mapping.splice(idx, 1);
      } else if (idx >= 0) {
        mapping[idx] = {
          ...mapping[idx],
          keyRefValue: next.source,
          valueRefValue: next.target
        };
      } else {
        mapping.push({
          type: 'Scheduling Location',
          keyRefType: 'CODE_VALUE_DISPLAY',
          keyRefValue: next.source,
          valueRefType: 'FACILITY_DISPLAY',
          valueRefValue: next.target
        } as ConfigurationMapping);
      }
      return { ...c, mapping };
    });
  }

  onDeleteRequested(): void {
    const id = this.selectedLocationId();
    if (!id) return;
    this._pendingDeleteId.set(id);
    this.deleteModalVisible.set(true);
  }

  cancelDelete(): void {
    this._pendingDeleteId.set(null);
    this.deleteModalVisible.set(false);
  }

  confirmDelete(): void {
    const id = this._pendingDeleteId();
    if (!id) return;
    this._config.update(c => {
      if (!c) return c;
      const workflows = (c.workflows ?? []).map(wf => {
        if (wf.meaning !== this.selectedWorkflow()) return wf;
        const filterSets = (wf.filterSets ?? []).filter(fs => fs.id !== id);
        return { ...wf, filterSets };
      });
      const removed = c.workflows?.find(wf => wf.meaning === this.selectedWorkflow())
        ?.filterSets?.find(fs => fs.id === id);
      const mappingSource = removed?.filters?.[0]?.options?.[0]?.item;
      const next = { ...c, workflows };
      if (mappingSource) {
        // Spread mapping to avoid mutating the original config's array reference.
        next.mapping = Array.isArray(next.mapping) ? [...next.mapping] : [];
        cascadeMappingRemoval(next, mappingSource, id);
      }
      return next;
    });
    if (this.selectedLocationId() === id) this.selectedLocationId.set(null);
    this._pendingDeleteId.set(null);
    this.deleteModalVisible.set(false);
  }

  private generateUniqueId(cfg: CompassConfiguration): string {
    const base = 'new-location';
    let candidate = base;
    let n = 1;
    const rawSubroute = toRawSubroute('prior-auth', this.selectedSubroute());
    while (!isUniqueId(cfg, this.selectedWorkflow(), 'prior-auth', rawSubroute, candidate, null)) {
      candidate = `${base}-${n++}`;
    }
    return candidate;
  }
}
